-- QA COPY of infra/bigquery/290_mk_market_orders.sql, generated by name mapping only
-- (mart.market_* -> mart_qa.mk_market_*, ref.client_markets / ref.naming_rules -> mart_qa.mk_*,
-- stg_customer_orders / stg_shoptet_orders -> mart_qa.mm1_* of migration 284). Do not edit by hand.

-- =============================================================================
-- 290_mk_market_orders.sql
-- Markets page (v1a, F2): one row per order with its market, the base every
-- other Markets object reads (291 spend split, 292 daily, 293 cohorts,
-- 294 forecast). Contract: docs/sessions/2026-10-15/markets/CONTRACT.md.
--
-- Creates
--   1. ref.client_markets              sold markets per client (+ local currency,
--                                      home flag). Drives the OTHER bucket, the
--                                      currency fallback and the single-market
--                                      spend default (291). Seeded below.
--   2. mart.sp_refresh_market_orders() rebuilds mart.market_orders
--   3. mart.market_orders              snapshot table (CALL at the end)
--
-- Reads stg only (raw is append-only and duplicated, audit I17):
--   stg.stg_customer_orders (amounts, new/returning, COGS, market country),
--   stg.stg_shopify_orders / stg.stg_woo_orders / stg.stg_shoptet_orders
--   (discounts, refunds, presentment currency, payment method),
--   stg.stg_shoptet_order_items (line discount flag), ref.clients,
--   ref.fx_rates. live/ files used: stg.stg_customer_orders.sql,
--   stg.stg_shopify_orders.sql, stg.stg_woo_orders.sql.
--
-- Depends on 284 (branch mm1-shoptet-market): stg_customer_orders carries the
-- Shoptet shipping_country (delivery country > pickup postcode > currency >
-- storefront) and country_source. Deploy 284 first; this file fails on the
-- missing column country_source otherwise.
--
-- Market rule (owner 2026-10-15): shipping country, then currency, then
-- storefront domain, then the client country.
--   Shopify     shipping_country                       -> market_source 'shipping'
--   WooCommerce billing_country (no shipping address    -> 'billing'
--               ingested, audit I2, fix F12)
--   Shoptet     284 country_source: delivery_country / pickup_postcode
--               -> 'shipping', currency -> 'currency', storefront_domain -> 'domain'
--   no country  order currency (Shopify presentment currency, else shop
--               currency) mapped through ref.client_markets.local_currency
--               -> 'currency'; else ref.clients.country -> 'client_default'.
--   `country` keeps the ISO-2 before bucketing (scouting reads it); `market`
--   is the country when it is a sold market of the client, else 'OTHER'.
--
-- Orders kept: everything stg keeps (cancelled already dropped) EXCEPT
--   non-shippable Shopify orders = no shipping country AND an amount
--   (HairQ tests, e-book, "payment only" and reshipment draft orders, customs
--   charges, subscription reactivation: audit I3, Dobias 60 orders L12M).
--   Migrated Dobias orders with no country and NULL amounts (Matrixify,
--   2013 to 2023) are kept: they carry customer history only (money NULL,
--   market by currency), dropping them would turn later orders into false
--   first orders (same reasoning as 258).
--
-- New customer: first kept order of the customer key (lower-cased email)
--   inside the data history. Ordering = order_date, then stg's own flag
--   (so same-day ties resolve as stg does), then order_id. Differs from stg
--   only where the first stg order was non-shippable. NULL without email.
--   first_order_market / first_order_date: market and date of that order,
--   frozen for every order of the customer (cohort key).
--
-- Money: base currency (ref.clients.currency) ex VAT, as stg; Manami
--   (non VAT payer) revenue is the Shoptet order total incl. shipping and
--   payment fee (METRICS.md). NULL means "not available", never 0:
--   gross_sales / discounts / refunds / shipping_charged NULL for Shoptet,
--   refunds NULL for Dobias (I6), cogs NULL when not costed (RawBark, I10).
--   fx_local_to_base: 1 when local = base, else ref.fx_rates local->base for
--   the order month, else 1 / (base->local); NULL when neither exists
--   (Dobias CAD after 2026-05, I5): the UI shows the local toggle as n/a.
--
-- Additive columns beyond CONTRACT.md (flagged in DATA-BUILD.md): country,
--   first_order_date.
--
-- Refresh: hourly, via mart.sp_refresh_markets() (294) in the console
--   scheduled query rpt_refresh_hourly. The CALL below bootstraps the table so
--   291 can read it (snapshot trap: a later migration reads the table, not
--   this procedure, so it must be built first).
-- QA copy: infra/bigquery/qa/290_mk_market_orders_qa.sql (mart_qa.mk_*,
--   reads mart_qa.mm1_stg_customer_orders / mm1_stg_shoptet_orders).
-- =============================================================================

-- -----------------------------------------------------------------------------
-- 1. ref.client_markets
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `oneeighty-warehouse.mart_qa.mk_client_markets`
(
  client_id STRING NOT NULL,
  market STRING NOT NULL OPTIONS(description="ISO-2 country the client actively sells to. Countries not listed land in market 'OTHER'."),
  local_currency STRING NOT NULL OPTIONS(description="Currency customers of this market pay in. Used for the currency fallback of the market rule and for the local-currency toggle."),
  is_home BOOL NOT NULL OPTIONS(description="Home market = the index base (home = 100) and the CM2 reference of the status chips. One per client."),
  note STRING,
  updated_at TIMESTAMP NOT NULL
)
CLUSTER BY client_id
OPTIONS(description="Sold markets per client for the Markets page (migration 290). One client with a single row is a single-market client: its unallocated paid spend defaults to that market (291).");

MERGE `oneeighty-warehouse.mart_qa.mk_client_markets` t
USING (
  SELECT * FROM UNNEST([
    STRUCT('dobias' AS client_id, 'US' AS market, 'USD' AS local_currency, TRUE AS is_home, 'largest market; company country in ref.clients is CA' AS note),
    STRUCT('dobias', 'CA', 'CAD', FALSE, 'Canadian store migrated into the US Shopify 2026-03 (orders in USD shop money, CAD presentment)'),
    STRUCT('rawbark', 'CZ', 'CZK', TRUE, CAST(NULL AS STRING)),
    STRUCT('rawbark', 'SK', 'EUR', FALSE, 'market = billing country until F12'),
    STRUCT('manami', 'CZ', 'CZK', TRUE, CAST(NULL AS STRING)),
    STRUCT('manami', 'SK', 'EUR', FALSE, 'market per 284 (pickup postcode, then currency)'),
    STRUCT('venev', 'CZ', 'CZK', TRUE, 'shop base currency EUR, CZ customers pay CZK'),
    STRUCT('venev', 'SK', 'EUR', FALSE, CAST(NULL AS STRING)),
    STRUCT('ethia', 'CZ', 'CZK', TRUE, 'single market')
  ])
) s
ON t.client_id = s.client_id AND t.market = s.market
WHEN NOT MATCHED THEN
  INSERT (client_id, market, local_currency, is_home, note, updated_at)
  VALUES (s.client_id, s.market, s.local_currency, s.is_home, s.note, CURRENT_TIMESTAMP());

-- -----------------------------------------------------------------------------
-- 2. mart.sp_refresh_market_orders
-- -----------------------------------------------------------------------------
CREATE OR REPLACE PROCEDURE `oneeighty-warehouse.mart_qa.mk_sp_refresh_market_orders`()
OPTIONS (description = 'Rebuilds mart.market_orders (one row per kept order with market, market source, new-customer flag, frozen first-order market, money in base currency, local currency and fx) from stg. Builds mart.market_orders__next, checks it (rows > 0, >= 90 % of the current table, unique client and order, no NULL market), then swaps it in. Any failure leaves the current table untouched. Migration 290. Called by mart.sp_refresh_markets (294).')
BEGIN
  DECLARE prev_rows INT64;
  DECLARE new_rows INT64;
  DECLARE dup_rows INT64;
  DECLARE null_market INT64;

  SET @@query_label = 'feature:markets-refresh';

  SET prev_rows = (
    SELECT row_count FROM `oneeighty-warehouse.mart_qa`.__TABLES__
    WHERE table_id = 'mk_market_orders');

  CREATE OR REPLACE TABLE `oneeighty-warehouse.mart_qa.mk_market_orders__next`
  CLUSTER BY client_id, market, order_date
  OPTIONS (description = 'Staging copy for mart.sp_refresh_market_orders. Not for reading.')
  AS
  WITH
  clients AS (
    SELECT client_id, currency AS currency_base, UPPER(country) AS client_country
    FROM `oneeighty-warehouse.ref.clients`
  ),
  sold AS (
    SELECT client_id, market, local_currency FROM `oneeighty-warehouse.mart_qa.mk_client_markets`
  ),
  currency_market AS (   -- currency -> market only where the currency names one market
    SELECT client_id, local_currency, ANY_VALUE(market) AS market
    FROM sold GROUP BY client_id, local_currency HAVING COUNT(*) = 1
  ),
  fx AS (
    SELECT month_start, from_currency, to_currency, rate FROM `oneeighty-warehouse.ref.fx_rates`
  ),
  shopify AS (
    SELECT client_id, order_id, total_discounts, total_refunded,
      COALESCE(NULLIF(TRIM(presentment_currency), ''), currency_original) AS currency_local,
      NULLIF(TRIM(JSON_VALUE(payload_json, '$.payment_gateway_names[0]')), '') AS payment_method,
      (NULLIF(TRIM(shipping_country), '') IS NULL AND subtotal_price IS NOT NULL) AS is_non_shippable
    FROM `oneeighty-warehouse.stg.stg_shopify_orders`
  ),
  woo AS (
    SELECT client_id, order_id, total_discounts, total_refunded,
      currency_original AS currency_local,
      NULLIF(TRIM(payment_method), '') AS payment_method
    FROM `oneeighty-warehouse.stg.stg_woo_orders`
  ),
  shoptet AS (
    SELECT client_id, order_code AS order_id, currency AS currency_local,
      NULLIF(TRIM(payment_method), '') AS payment_method
    FROM `oneeighty-warehouse.mart_qa.mm1_stg_shoptet_orders`
  ),
  shoptet_disc AS (      -- line discount flag only: Shoptet amounts are not ingested
    SELECT client_id, order_code AS order_id, LOGICAL_OR(discount_pct > 0) AS has_line_discount
    FROM `oneeighty-warehouse.stg.stg_shoptet_order_items`
    GROUP BY client_id, order_code
  ),
  joined AS (
    SELECT
      o.platform, o.client_id, o.order_id, o.order_date, o.customer_key, o.is_returning_customer,
      o.revenue, o.net_sales, o.shipping, o.cogs, o.gross_profit, o.country_source,
      NULLIF(UPPER(TRIM(o.shipping_country)), '') AS ship_country,
      c.currency_base, c.client_country,
      CASE o.platform WHEN 'shopify' THEN s.total_discounts WHEN 'woocommerce' THEN w.total_discounts END AS discounts,
      CASE o.platform WHEN 'shopify' THEN s.total_refunded  WHEN 'woocommerce' THEN w.total_refunded  END AS refunds,
      COALESCE(s.currency_local, w.currency_local, t.currency_local, o.market_currency) AS currency_local,
      COALESCE(s.payment_method, w.payment_method, t.payment_method) AS payment_method,
      IFNULL(s.is_non_shippable, FALSE) AS is_non_shippable,
      td.has_line_discount
    FROM `oneeighty-warehouse.mart_qa.mm1_stg_customer_orders` o
    JOIN clients c ON c.client_id = o.client_id
    LEFT JOIN shopify s      ON o.platform = 'shopify'     AND s.client_id = o.client_id AND s.order_id = o.order_id
    LEFT JOIN woo w          ON o.platform = 'woocommerce' AND w.client_id = o.client_id AND w.order_id = o.order_id
    LEFT JOIN shoptet t      ON o.platform = 'shoptet'     AND t.client_id = o.client_id AND t.order_id = o.order_id
    LEFT JOIN shoptet_disc td ON o.platform = 'shoptet'    AND td.client_id = o.client_id AND td.order_id = o.order_id
  ),
  located AS (
    SELECT
      j.*,
      COALESCE(j.ship_country, cm.market, j.client_country) AS country,
      CASE
        WHEN j.ship_country IS NOT NULL THEN
          CASE
            WHEN j.platform = 'woocommerce' THEN 'billing'
            WHEN j.platform = 'shoptet' AND j.country_source = 'currency' THEN 'currency'
            WHEN j.platform = 'shoptet' AND j.country_source = 'storefront_domain' THEN 'domain'
            ELSE 'shipping'
          END
        WHEN cm.market IS NOT NULL THEN 'currency'
        ELSE 'client_default'
      END AS market_source
    FROM joined j
    LEFT JOIN currency_market cm
      ON cm.client_id = j.client_id AND cm.local_currency = j.currency_local
    WHERE NOT j.is_non_shippable
  ),
  bucketed AS (
    SELECT l.*, IF(s.market IS NOT NULL, l.country, 'OTHER') AS market
    FROM located l
    LEFT JOIN sold s ON s.client_id = l.client_id AND s.market = l.country
  ),
  sequenced AS (
    SELECT
      b.*,
      IF(b.customer_key IS NULL, NULL,
         ROW_NUMBER() OVER w = 1)                                  AS is_new_customer,
      IF(b.customer_key IS NULL, NULL, FIRST_VALUE(b.market) OVER w) AS first_order_market,
      IF(b.customer_key IS NULL, NULL, FIRST_VALUE(b.order_date) OVER w) AS first_order_date
    FROM bucketed b
    WINDOW w AS (
      PARTITION BY b.client_id, b.customer_key
      ORDER BY b.order_date, IF(b.is_returning_customer IS FALSE, 0, 1), b.order_id)
  )
  SELECT
    q.client_id,
    q.order_id,
    q.order_date,
    q.platform,
    q.market,
    q.country,
    q.market_source,
    q.customer_key,
    q.is_new_customer,
    q.first_order_market,
    q.first_order_date,
    q.currency_base,
    q.currency_local,
    CAST(CASE
      WHEN q.currency_local = q.currency_base THEN 1
      ELSE COALESCE(f1.rate, SAFE_DIVIDE(1, f2.rate))
    END AS NUMERIC)                                                     AS fx_local_to_base,
    IF(q.discounts IS NULL, NULL, q.net_sales + q.discounts)            AS gross_sales,
    q.discounts,
    q.refunds,
    q.net_sales,
    IF(q.platform = 'shoptet', NULL, q.shipping)                        AS shipping_charged,
    q.revenue                                                           AS net_revenue,
    q.cogs,
    q.gross_profit,
    CASE q.platform
      WHEN 'shoptet' THEN IFNULL(q.has_line_discount, FALSE)
      ELSE IFNULL(q.discounts, 0) > 0
    END                                                                 AS is_discounted,
    q.payment_method,
    IF(q.payment_method IS NULL, NULL,
       REGEXP_CONTAINS(LOWER(q.payment_method),
         r'dob[ií]rk|cash on delivery|(^|[^a-z])cod([^a-z]|$)'))       AS is_cod,
    IF(q.platform = 'shoptet' OR q.shipping IS NULL, NULL, q.shipping = 0) AS is_zero_shipping
  FROM sequenced q
  LEFT JOIN fx f1
    ON f1.from_currency = q.currency_local AND f1.to_currency = q.currency_base
   AND f1.month_start = DATE_TRUNC(q.order_date, MONTH)
  LEFT JOIN fx f2
    ON f2.from_currency = q.currency_base AND f2.to_currency = q.currency_local
   AND f2.month_start = DATE_TRUNC(q.order_date, MONTH);

  SET new_rows = (SELECT COUNT(*) FROM `oneeighty-warehouse.mart_qa.mk_market_orders__next`);
  SET dup_rows = (
    SELECT COUNT(*) - COUNT(DISTINCT CONCAT(client_id, '|', order_id))
    FROM `oneeighty-warehouse.mart_qa.mk_market_orders__next`);
  SET null_market = (
    SELECT COUNTIF(market IS NULL) FROM `oneeighty-warehouse.mart_qa.mk_market_orders__next`);

  ASSERT new_rows > 0 AS 'market_orders: new build is empty';
  ASSERT dup_rows = 0 AS 'market_orders: duplicate client_id + order_id';
  ASSERT null_market = 0 AS 'market_orders: order without market';
  ASSERT prev_rows IS NULL OR new_rows >= 0.9 * prev_rows
    AS 'market_orders: new build has under 90 % of the current rows';

  CREATE OR REPLACE TABLE `oneeighty-warehouse.mart_qa.mk_market_orders`
  COPY `oneeighty-warehouse.mart_qa.mk_market_orders__next`;
  ALTER TABLE `oneeighty-warehouse.mart_qa.mk_market_orders`
  SET OPTIONS (description = 'Markets: one row per kept order with market (ISO-2 or OTHER), market source, new-customer flag, frozen first-order market, money in base currency ex VAT, local currency + fx. Built by mart.sp_refresh_market_orders (migration 290). Read by 291 to 294 and the Markets page.');
  DROP TABLE `oneeighty-warehouse.mart_qa.mk_market_orders__next`;
END;

CALL `oneeighty-warehouse.mart_qa.mk_sp_refresh_market_orders`();
